        label.Size = UDim2.new(0.42, 0, 1, 0)
        label.BackgroundTransparency = 1
        label.Text = labelText
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.Font = Enum.Font.Highway
        label.TextSize = 13
        label.TextColor3 = Color3.fromRGB(240, 240, 240)
